const q = $('Test questions').item.json;
const v = $json.embedding.values;

if (v.length !== 3072) {
  throw new Error(`Expected 3072 numbers, got ${v.length}`);
}

return {
  json: {
    question: q.question,
    accept: q.accept,
    embedding: '[' + v.join(',') + ']'
  }
};

const q = $('Format vector').item.json;
let results = $json.results;
if (typeof results === 'string') results = JSON.parse(results);

const isMatch = (r) => q.accept.some((a) => {
  const [file, sec] = a.split('|');
  return r.source.startsWith(file) && r.section.toLowerCase().includes(sec);
});

const outOfScope = q.accept.length === 0;
const rank = outOfScope ? null : results.findIndex(isMatch) + 1;

return {
  json: {
    question: q.question,
    type: outOfScope ? 'out_of_scope' : 'in_scope',
    hit_top3: outOfScope ? null : rank > 0,
    rank: rank,
    top1_similarity: results[0].similarity,
    retrieved: results
      .map((r) => `${r.source.slice(0, 2)} > ${r.section} (${r.similarity})`)
      .join(' | ')
  }
};

const rows = $input.all().map((i) => i.json);
const inScope = rows.filter((r) => r.type === 'in_scope');
const oos = rows.filter((r) => r.type === 'out_of_scope');

const top3 = inScope.filter((r) => r.hit_top3).length;
const top1 = inScope.filter((r) => r.rank === 1).length;
const sims = (arr) => arr.map((r) => Number(r.top1_similarity));
const goodSims = sims(inScope.filter((r) => r.rank === 1));

return [{
  json: {
    in_scope_total: inScope.length,
    top3_rate: Math.round((100 * top3) / inScope.length) + '%',
    top1_rate: Math.round((100 * top1) / inScope.length) + '%',
    misses: inScope.filter((r) => !r.hit_top3).map((r) => r.question),
    in_scope_top1_similarity_min: Math.min(...goodSims),
    out_of_scope_max_similarity: Math.max(...sims(oos)),
    out_of_scope: oos.map((r) => `${r.question} -> ${r.top1_similarity}`)
  }
}];
